		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 20, "<script>\n  // WebSocket connection for real-time collaboration\n  let ws = null;\n\n  function connectWebSocket() {\n    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';\n    const wsUrl = `${protocol}//${window.location.host}/api/builder/ws`;\n\n    ws = new WebSocket(wsUrl);\n\n    ws.onopen = function (event) {\n      console.log('✅ WebSocket connected');\n      window.builderState.isConnected = true;\n      updateConnectionStatus(true);\n    };\n\n    ws.onmessage = function (event) {\n      const data = JSON.parse(event.data);\n      handleWebSocketMessage(data);\n    };\n\n    ws.onclose = function (event) {\n      console.log('❌ WebSocket disconnected');\n      window.builderState.isConnected = false;\n      updateConnectionStatus(false);\n\n      // Attempt to reconnect after 3 seconds\n      setTimeout(connectWebSocket, 3000);\n    };\n\n    ws.onerror = function (error) {\n      console.error('WebSocket error:', error);\n    };\n  }\n\n  function handleWebSocketMessage(data) {\n    switch (data.type) {\n      case 'component_added':\n        // Add component to canvas\n        refreshCanvas();\n        break;\n\n      case 'component_updated':\n        // Update component on canvas\n        updateCanvasComponent(data.data);\n        break;\n\n      case 'component_deleted':\n        // Remove component from canvas\n        removeCanvasComponent(data.data.id);\n        break;\n\n      case 'schema_updated':\n        // Refresh entire canvas\n        refreshCanvas();\n        break;\n\n      case 'user_joined':\n        showToast(`${data.data.name} joined the session`, 'info');\n        break;\n\n      case 'user_left':\n        showToast(`${data.data.name} left the session`, 'info');\n        break;\n    }\n  }\n\n  function updateConnectionStatus(connected) {\n    const indicator = document.getElementById('connection-indicator');\n    if (indicator) {\n      if (connected) {\n        indicator.className = 'w-2 h-2 bg-green-500 rounded-full';\n        indicator.title = 'Connected';\n      } else {\n        indicator.className = 'w-2 h-2 bg-red-500 rounded-full';\n        indicator.title = 'Disconnected';\n      }\n    }\n  }\n\n  function refreshCanvas() {\n    // Reload canvas content\n    window.location.reload();\n  }\n\n  function updateCanvasComponent(componentData) {\n    const element = document.querySelector(`[data-component-id=\"${componentData.id}\"]`);\n    if (element) {\n      // Update component position and properties\n      element.style.left = componentData.position.x + 'px';\n      element.style.top = componentData.position.y + 'px';\n      element.style.width = componentData.size.width + 'px';\n      element.style.height = componentData.size.height + 'px';\n    }\n  }\n\n  function removeCanvasComponent(componentId) {\n    const element = document.querySelector(`[data-component-id=\"${componentId}\"]`);\n    if (element) {\n      element.remove();\n    }\n  }\n\n  // Connect on page load\n  document.addEventListener('DOMContentLoaded', function () {\n    connectWebSocket();\n  });\n</script>")
